const messages = $json.messages;

// Always pick the SENT message as the anchor
const sentMessage = messages.find(
  m => m.labelIds && m.labelIds.includes("SENT")
);

if (!sentMessage) {
  throw new Error("No SENT message found in thread");
}

const headers = sentMessage.payload.headers;

const messageIdHeader = headers.find(
  h => h.name.toLowerCase() === "message-id"
);

const toHeader = headers.find(
  h => h.name.toLowerCase() === "to"
);

return {
  json: {
    Email: toHeader.value,
    Name: $input.item.json.Name,
    threadId: $json.id,
    messageId: messageIdHeader.value.replace(/[<>]/g, "")
  }
};

const input = $input.item.json;

// Get name
const firstName = $('Loop1').first().json["First Name"] || $('Loop2').first().json.Name || "there";

const subject = "You are probably not seeing this!!";
const from = "vamsi@lumoscale.com";
const to = input.Email;
const threadId = input.threadId || input["ThreadID 2"] || input["ThreadID"];
const messageId = input.messageId;

const htmlBody = `
<p>Hi ${firstName},</p>

<p>Following up on my last note.</p>

<p>Here's what I'm seeing: agents think they need more marketing. But they're already getting calls they're not answering.</p>

<p>One missed call during a showing = one buyer who went to your competitor.</p>

<p>You're probably losing thousands per month just from unanswered calls.</p>

<p>Want to know your actual number?</p>

<p>Vamsi</p>
`;

const emailContent =
`Subject: ${subject}
From: ${from}
To: ${to}
In-Reply-To: <${messageId}>
References: <${messageId}>
Content-Type: text/html; charset="UTF-8"

${htmlBody}`;

const raw = Buffer.from(emailContent)
  .toString("base64")
  .replace(/\\+/g, "-")
  .replace(/\\//g, "_")
  .replace(/=+$/, "");

return {
  json: {
    raw,
    threadId
  }
};

